package com.myassist.assistant.ui;
import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.myassist.assistant.MyAssistApp;
public class ProfileActivity extends AppCompatActivity{protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_profile);((TextView)findViewById(R.id.tvName)).setText(MyAssistApp.session().fullName());((TextView)findViewById(R.id.tvRole)).setText(MyAssistApp.session().role());findViewById(R.id.btnLogout).setOnClickListener(v->{MyAssistApp.session().clear();startActivity(new Intent(this,LoginActivity.class));finishAffinity();});}}